import re
from datetime import datetime

_DIGITS = "0123456789"
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_ZIP4_RE = re.compile(r"([0-9]+)-([0-9]{4})")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_OPT_OUT = {"y", "yes", "true", "1"}


def _normalize_email(raw):
    s = raw or ""
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+")[0]
            s = local + "@gmail.com"
    return s


def _email_valid(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")


def _normalize_phone(raw):
    s = raw or ""
    m = _EXT_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    s = (raw or "").strip()
    m = _ZIP4_RE.fullmatch(s)
    if m:
        s = m.group(1)
    if len(s) == 4 and all(c in _DIGITS for c in s):
        s = "0" + s
    if len(s) == 5 and all(c in _DIGITS for c in s):
        return s
    return ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return datetime.min  # unparseable: treated as oldest


def dedupe_contacts(rows):
    # Normalize every row and drop those with neither valid email nor valid phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email"))
        if not _email_valid(email):
            email = ""
        phone = _normalize_phone(row.get("phone"))
        if not email and not phone:
            continue
        tags = set()
        for t in _TAG_SPLIT_RE.split(row.get("tags") or ""):
            t = t.strip().lower()
            if t:
                tags.add(t)
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": (row.get("source") or "").strip().lower(),
            "tags": tags,
            "opted_out": (row.get("opted_out") or "").strip().lower() in _OPT_OUT,
            "updated": _parse_updated(row.get("updated")),
        })

    # Union-find over the kept records.
    parent = list(range(len(recs)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(i, by_email[r["email"]])
            else:
                by_email[r["email"]] = i
        last = r["last_name"].lower()
        if r["phone"] and last:
            key = (r["phone"], last)
            if key in by_phone_last:
                union(i, by_phone_last[key])
            else:
                by_phone_last[key] = i

    groups = {}
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(recs[i])

    def pick(group, field):
        cands = [r for r in group if r[field]]
        if not cands:
            return ""
        best = min(
            cands,
            key=lambda r: (r["source"] != "manual", -r["updated"].timestamp()
                           if r["updated"] != datetime.min else float("inf"),
                           r["idx"]),
        )
        return best[field]

    ordered = sorted(groups.values(), key=lambda g: min(r["idx"] for r in g))

    result = []
    for g in ordered:
        tags = set()
        for r in g:
            tags |= r["tags"]
        latest = max(r["updated"] for r in g)
        result.append({
            "first_name": pick(g, "first_name"),
            "last_name": pick(g, "last_name"),
            "zip": pick(g, "zip"),
            "email": pick(g, "email"),
            "phone": pick(g, "phone"),
            "source": pick(g, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in g) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return result
